def task_func(goals, penalties, csv_file_path=CSV_FILE_PATH):
    goals = goals or {}
    penalties = penalties or {}

    # Incremental totals: only the values supplied in this call.
    total_goals = sum(goals.values())
    total_penalties = sum(penalties.values())

    header = ['team', 'goals', 'penalties']
    rows = []
    if os.path.exists(csv_file_path):
        try:
            with open(csv_file_path, 'r', newline='') as file:
                reader = csv.reader(file)
                data = [row for row in reader if row]
            if data:
                header = data[0]
                rows = data[1:]
        except (OSError, csv.Error):
            header = ['team', 'goals', 'penalties']
            rows = []

    # Normalise header positions.
    try:
        team_idx = header.index('team')
    except ValueError:
        team_idx = 0
    try:
        goals_idx = header.index('goals')
    except ValueError:
        goals_idx = 1
    try:
        penalties_idx = header.index('penalties')
    except ValueError:
        penalties_idx = 2

    def _to_int(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            try:
                return int(float(value))
            except (TypeError, ValueError):
                return 0

    # Index existing rows by team.
    existing = {}
    ordered_teams = []
    for row in rows:
        row = list(row)
        while len(row) <= max(team_idx, goals_idx, penalties_idx):
            row.append('0')
        team = row[team_idx]
        if team not in existing:
            ordered_teams.append(team)
        existing[team] = row

    # Merge goals.
    for team, value in goals.items():
        if team not in existing:
            row = ['0'] * len(header)
            row[team_idx] = team
            existing[team] = row
            ordered_teams.append(team)
        row = existing[team]
        row[goals_idx] = str(_to_int(row[goals_idx]) + _to_int(value))

    # Merge penalties.
    for team, value in penalties.items():
        if team not in existing:
            row = ['0'] * len(header)
            row[team_idx] = team
            existing[team] = row
            ordered_teams.append(team)
        row = existing[team]
        row[penalties_idx] = str(_to_int(row[penalties_idx]) + _to_int(value))

    directory = os.path.dirname(csv_file_path)
    if directory and not os.path.exists(directory):
        os.makedirs(directory, exist_ok=True)

    with open(csv_file_path, 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerow(header)
        for team in ordered_teams:
            writer.writerow(existing[team])

    return Counter({'goals': total_goals, 'penalties': total_penalties})

import pandas as pd
import os
import glob
def task_func(my_list, file_dir='./data_files/', file_ext='.csv'):
    if not isinstance(my_list, list):
        raise TypeError("'my_list' must be a list.")

    my_list.append(12)

    try:
        num_files = int(sum(int(x) for x in my_list))
    except (TypeError, ValueError):
        num_files = len(my_list)

    if not os.path.isdir(file_dir):
        raise FileNotFoundError(f"No files found in directory: {file_dir}")

    pattern = os.path.join(file_dir, '*' + file_ext)
    files = sorted(glob.glob(pattern))
    if not files:
        raise FileNotFoundError(f"No files found in directory: {file_dir}")

    selected = files[:num_files]
    if not selected:
        raise FileNotFoundError(f"No files found in directory: {file_dir}")

    dataframes = [pd.read_csv(f) for f in selected]
    return pd.concat(dataframes, ignore_index=True)

import pandas as pd
from datetime import datetime, timedelta
from random import randint, seed as random_seed
def task_func(start_date=datetime(2020, 1, 1), end_date=datetime(2020, 12, 31), seed=42):
    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise ValueError("start_date and end_date must be datetime.datetime instances")
    if start_date > end_date:
        raise ValueError("start_date must not be later than end_date")

    random_seed(seed)
    total_days = (end_date - start_date).days
    dates = [start_date + timedelta(days=randint(0, total_days)) for _ in range(total_days)]
    return pd.Series(dates)
